  if (!isRecord(raw)) return raw;
  if (flag !== undefined) return { ...raw, model: flag };
  if ("model" in raw) return raw;
  const fromEnv = process.env.DECISION_MODEL;
  return fromEnv === undefined ? raw : { ...raw, model: fromEnv };
